CREATE TABLE IF NOT EXISTS user_books (id TEXT PRIMARY KEY, uid TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, chars INT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_user_books_uid ON user_books (uid, created_at DESC); CREATE TABLE IF NOT EXISTS user_history (id BIGSERIAL PRIMARY KEY, uid TEXT NOT NULL, kind TEXT NOT NULL, title TEXT, detail JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_user_history_uid ON user_history (uid, created_at DESC);
